import { Theme } from './settings/types';
import { NextBranchIPhoneHomeDeparturesSearch } from './components/generated/NextBranchIPhoneHomeDeparturesSearch';

let theme: Theme = 'light';

function App() {
  function setTheme(theme: Theme) {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }

  setTheme(theme);

  return (
    <>
      <NextBranchIPhoneHomeDeparturesSearch />
    </>
  ); // %EXPORT_STATEMENT%
}

export default App;

