const LED = ({
  value,
  scale = 1,
  tint = "#FFAA25"
}: {
  value: string;
  scale?: number;
  tint?: string;
}) => <span aria-label={value} style={{
  display: "inline-flex",
  alignItems: "center",
  gap: 1.65 * scale,
  whiteSpace: "nowrap",
  flexShrink: 0
}}>{value.toUpperCase().split("").map((c, k) => <span key={k} aria-hidden="true" style={{
    display: "grid",
    gridTemplateColumns: "repeat(5,1fr)",
    gridTemplateRows: "repeat(7,1fr)",
    gap: .6 * scale,
    flexShrink: 0
  }}>{(glyphs[c] || glyphs[" "]).flatMap((line, r) => line.split("").map((on, i) => <span key={r + "_" + i} style={{
      width: 1.72 * scale,
      height: 1.72 * scale,
      borderRadius: "30%",
      background: on === "1" ? tint : "#211B10",
      opacity: on === "1" ? 1 : .58,
      boxShadow: on === "1" ? "0 0 2.5px #FF7B00B8" : "none"
    }} />))}</span>)}</span>;
export const NextBranchIPhoneHomeDeparturesSearch = () => {
  const [page, setPage] = useState("home"),
    [saved, setSaved] = useState<P[]>(sample),
    [active, setActive] = useState<P>(sample[0]),
    [selected, setSelected] = useState(""),
    [query, setQuery] = useState(""),
    [boardStyle, setBoardStyle] = useState<"matrix" | "modern" | "custom">("matrix"),
    [cardStyles, setCardStyles] = useState<Record<string, "matrix" | "modern">>({}),
    [editingCard, setEditingCard] = useState<P | null>(null),
    [dark, setDark] = useState(true),
    [stale, setStale] = useState(false),
    [incoming, setIncoming] = useState<P | null>(null),
    [undo, setUndo] = useState<P[] | null>(null),
    [recent, setRecent] = useState<string[]>([]),
    [dragging, setDragging] = useState<string | null>(null),
    [dragTarget, setDragTarget] = useState<string | null>(null),
    [pull, setPull] = useState(0),
    [refreshing, setRefreshing] = useState(false);
  const touchStart = useRef<number | null>(null),
    pullTimer = useRef<ReturnType<typeof setTimeout> | null>(null),
    dragFrom = useRef<string | null>(null),
    dragTo = useRef<string | null>(null);
  const reorder = (from: string, to: string) => setSaved(current => {
    const a = current.findIndex(p => p.id === from),
      b = current.findIndex(p => p.id === to);
    if (a < 0 || b < 0 || a === b) return current;
    const next = [...current];
    const [item] = next.splice(a, 1);
    next.splice(b, 0, item);
    return next;
  });
  const selectStation = (name: string) => {
    setRecent(current => [name, ...current.filter(n => n !== name)].slice(0, 2));
    setSelected(name);
    setPage("platforms");
  };
  const refreshAll = () => {
    setRefreshing(true);
    setStale(false);
    setTimeout(() => {
      setRefreshing(false);
      setPull(0);
    }, 800);
  };
  const bg = dark ? "#0B0B0D" : "#F2F2F3",
    surface = dark ? "#171719" : "#FFFFFF",
    fg = dark ? "#ECEDEF" : "#222528",
    dim = dark ? "#929398" : "#60646B",
    border = dark ? "#303033" : "#E0E0E2",
    muted = dark ? "#101011" : "#F5F5F6";
  const action = (label: string, cb: () => void, primary = false) => <button onClick={cb} style={{
    border: "1px solid " + (primary ? "#444A52" : border),
    borderRadius: 9,
    padding: "11px 13px",
    background: primary ? "#31343A" : surface,
    color: primary ? "white" : fg,
    fontSize: 13,
    fontWeight: 700,
    cursor: "pointer"
  }}>{label}</button>;
  const board = (p: P, expanded = false) => {
    const trains = p.trains.slice(0, expanded ? 5 : 3);
    const amber = (boardStyle === "custom" ? cardStyles[p.id] || "matrix" : boardStyle) === "matrix";
    const matrixBg = "radial-gradient(circle at center, #30281B 0.6px, transparent 1px) 0 0 / 6px 6px, #0C0C09";
    const modernBg = "radial-gradient(circle at center, #29303B 0.8px, transparent 1.4px) 0 0 / 7px 7px, #080C10";
    return <article key={p.id} role={!expanded ? "button" : undefined} tabIndex={!expanded ? 0 : undefined} onKeyDown={e => {
      if (!expanded && (e.key === "Enter" || e.key === " ")) {
        setActive(p);
        setPage("detail");
      }
    }} onClick={() => {
      if (!expanded) {
        setActive(p);
        setPage("detail");
      }
    }} style={{
      background: surface,
      border: "1px solid " + border,
      borderRadius: 10,
      overflow: "hidden",
      marginBottom: 10,
      cursor: expanded ? "default" : "pointer",
      boxShadow: "0 2px 8px #00000020"
    }}>
 <div style={{
        minHeight: 43,
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        padding: "0 10px 0 12px",
        gap: 8
      }}>
  <div style={{
          minWidth: 0,
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-start",
          gap: 3,
          padding: "7px 0"
        }}>
   <strong style={{
            fontSize: 15,
            fontWeight: 750,
            letterSpacing: "-.25px",
            maxWidth: "100%",
            overflow: "hidden",
            textOverflow: "ellipsis",
            whiteSpace: "nowrap"
          }}>{p.name}</strong>
   <span style={{
            fontSize: 11,
            color: dim,
            whiteSpace: "nowrap"
          }}>{p.direction} · {p.platform}</span>
  </div>
  <div style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-end",
          gap: 3,
          flexShrink: 0,
          maxWidth: "38%",
          padding: "6px 0"
        }}>
    {p.lines.map(line => <span key={line} style={{
            display: "inline-flex",
            alignItems: "center",
            gap: 5,
            fontSize: 10,
            fontWeight: 700,
            color: dim,
            textAlign: "right"
          }}>
      <span aria-hidden="true" style={{
              width: 15,
              height: 5,
              borderRadius: 2,
              flexShrink: 0,
              background: lineColours[line] || "#888",
              boxShadow: line === "Northern" ? "0 0 0 1px #A0A0A0" : "none"
            }} />
      {line} line
    </span>)}
  </div>
 </div>
 <div style={{
        background: amber ? matrixBg : modernBg,
        padding: "3px 9px 4px",
        borderTop: "1px solid " + (amber ? "#3D2E14" : "#1B3444"),
        borderBottom: "1px solid " + (amber ? "#3D2E14" : "#1B3444")
      }}>
 {trains.map((t, i) => {
          const text = t.dest + (t.via === "Branch unavailable" ? "" : " via " + t.via);
          const ledScale = text.length > 28 ? .61 : text.length > 22 ? .68 : .78;
          return <div key={i} style={{
            height: 37,
            display: "grid",
            gridTemplateColumns: amber ? "16px minmax(0,1fr) 62px" : "20px minmax(0,1fr) 73px",
            gap: amber ? 5 : 7,
            alignItems: "center",
            borderBottom: i < trains.length - 1 ? amber ? "1px solid #251F15" : "1px solid #4F9BBB" : "none"
          }}>
 {amber ? <><LED value={String(i + 1)} scale={.81} /><div style={{
                minWidth: 0,
                overflow: "hidden",
                display: "flex",
                alignItems: "center"
              }}><LED value={text} scale={ledScale} /></div><div style={{
                justifySelf: "end",
                display: "flex",
                alignItems: "center",
                gap: 4
              }}><LED value={String(t.min)} scale={.78} /><LED value="min" scale={.78} /></div></> : <>
 <span style={{
                color: "#B6E5FF",
                font: "300 16px 'Gill Sans','Avenir Next','Helvetica Neue',sans-serif"
              }}>{i + 1}.</span>
 <span style={{
                color: "#BDEBFF",
                font: "300 17px 'Gill Sans','Avenir Next','Helvetica Neue',sans-serif",
                letterSpacing: ".05px",
                overflow: "hidden",
                textOverflow: "ellipsis",
                whiteSpace: "nowrap",
                textShadow: "0 0 3px #4CB6F244"
              }}>{text}</span>
 <span style={{
                justifySelf: "end",
                color: "#BDEBFF",
                whiteSpace: "nowrap",
                font: "300 18px 'Gill Sans','Avenir Next','Helvetica Neue',sans-serif",
                letterSpacing: ".1px",
                textShadow: "0 0 3px #4CB6F244"
              }}>{t.min} {t.min === 1 ? "min" : "mins"}</span>
 </>}
 </div>;
        })}
 </div>
 <div style={{
        height: 23,
        padding: "0 10px 0 12px",
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        color: stale ? "#F2AC48" : dim,
        fontSize: 10
      }}>
 <span>{stale ? "⚠ Predictions may be outdated" : "● Updated just now"}</span>{expanded && <span>5 upcoming trains</span>}
 </div>
 </article>;
  };
  const save = (p: P) => {
    if (saved.some(v => v.id === p.id)) {
      setPage("home");
      return;
    }
    if (saved.length === 3) {
      setIncoming(p);
      setPage("manage");
    } else {
      setSaved([...saved, p]);
      setPage("home");
    }
  };
  const result = (title: string, sub: string, onClick: () => void) => <button onClick={onClick} style={{
    width: "100%",
    minHeight: 52,
    background: surface,
    color: fg,
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    padding: "10px 13px",
    border: "1px solid " + border,
    borderRadius: 10,
    marginBottom: 8,
    textAlign: "left",
    cursor: "pointer"
  }}><span><b style={{
        fontSize: 14
      }}>{title}</b><span style={{
        display: "block",
        fontSize: 11,
        color: dim,
        marginTop: 4
      }}>{sub}</span></span><ChevronRight size={17} /></button>;
  const heading = (title: string) => <header style={{
    height: 48,
    background: surface,
    borderBottom: "1px solid " + border,
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    padding: "0 15px",
    flexShrink: 0
  }}><div style={{
      display: "flex",
      alignItems: "center",
      gap: 9
    }}>{page !== "home" && <button aria-label="Back" onClick={() => setPage(page === "ui" ? "settings" : page === "editCard" ? "manage" : "home")} style={{
        background: "none",
        border: 0,
        color: fg,
        cursor: "pointer",
        padding: 4
      }}><ChevronLeft size={19} /></button>}<strong style={{
        fontSize: page === "home" ? 18 : 17,
        letterSpacing: "-.5px"
      }}>{title}</strong></div>{page === "home" ? <button aria-label="Search" onClick={() => {
      setQuery("");
      setPage("search");
    }} style={{
      background: "none",
      color: fg,
      border: 0,
      padding: 7,
      cursor: "pointer"
    }}><Search size={21} /></button> : <span style={{
      background: "#E32017",
      height: 6,
      width: 6,
      borderRadius: 9
    }} />}</header>;
  return <div style={{
    minHeight: 900,
    background: bg,
    display: "flex",
    justifyContent: "center",
    alignItems: "flex-start",
    paddingTop: 17,
    fontFamily: "Avenir Next, Gill Sans, Helvetica Neue, sans-serif",
    color: fg
  }}><div style={{
      width: 390,
      height: 845,
      maxWidth: "100%",
      border: "7px solid #030304",
      borderRadius: 43,
      overflow: "hidden",
      background: bg,
      display: "flex",
      flexDirection: "column",
      boxShadow: "0 22px 48px #0008"
    }}><div style={{
        height: 36,
        background: surface,
        flexShrink: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        padding: "0 22px",
        fontSize: 12,
        fontWeight: 800
      }}>9:41 <span>●●● ▰ ▰</span></div>

{page === "home" && <>{heading("NextBranch")}<div onTouchStart={e => {
          if (e.currentTarget.scrollTop <= 0 && !refreshing) touchStart.current = e.touches[0].clientY;
        }} onTouchMove={e => {
          if (touchStart.current === null || refreshing) return;
          const distance = Math.max(0, Math.min(90, e.touches[0].clientY - touchStart.current));
          setPull(distance);
          if (distance >= 60 && !pullTimer.current) pullTimer.current = setTimeout(() => {
            pullTimer.current = null;
            touchStart.current = null;
            refreshAll();
          }, 650);
          if (distance < 60 && pullTimer.current) {
            clearTimeout(pullTimer.current);
            pullTimer.current = null;
          }
        }} onTouchEnd={() => {
          touchStart.current = null;
          if (pullTimer.current) {
            clearTimeout(pullTimer.current);
            pullTimer.current = null;
          }
          if (!refreshing) setPull(0);
        }} onTouchCancel={() => {
          touchStart.current = null;
          if (pullTimer.current) clearTimeout(pullTimer.current);
          pullTimer.current = null;
          setPull(0);
        }} style={{
          flex: 1,
          overflowY: "auto",
          padding: "12px 12px 14px"
        }}>
{(pull > 8 || refreshing) && <div role="status" style={{
            textAlign: "center",
            color: dim,
            fontSize: 11,
            padding: "6px 0 12px"
          }}>{refreshing ? "Refreshing…" : pull >= 60 ? "Hold to refresh" : "Pull down to refresh"}</div>}
<div style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            marginBottom: 11
          }}>
 <div style={{
              display: "flex",
              gap: 7,
              alignItems: "baseline"
            }}><strong style={{
                fontSize: 14,
                fontWeight: 700
              }}>Saved platforms</strong><span style={{
                color: dim,
                fontSize: 11
              }}>{saved.length}/3</span></div>
 <div style={{
              display: "flex",
              gap: 5,
              alignItems: "center"
            }}>
 <button title="Manage saved platforms" aria-label="Manage saved platforms" onClick={() => setPage("manage")} style={{
                background: "transparent",
                border: 0,
                color: dim,
                padding: "6px",
                cursor: "pointer"
              }}><span style={{
                  fontSize: 11,
                  fontWeight: 700
                }}>Manage platforms</span></button>
 <button title="Settings" aria-label="Settings" onClick={() => setPage("settings")} style={{
                background: "transparent",
                border: 0,
                color: dim,
                padding: 6,
                cursor: "pointer"
              }}><Settings2 size={16} /></button>
 </div>
 </div>
 {saved.map(p => board(p))}
 {saved.length < 3 && action("+ Add a platform", () => setPage("search"))}
 {undo && <button onClick={() => {
            setSaved(undo);
            setUndo(null);
          }} style={{
            color: "#F2B047",
            background: "transparent",
            border: 0,
            fontSize: 12
          }}>Undo removal</button>}
 <div style={{
            padding: "5px 2px",
            color: dim,
            fontSize: 10
          }}>Illustrative departures · Not live</div>
 </div></>}

{page === "detail" && <>{heading("Platform departures")}<div style={{
          padding: 12,
          overflowY: "auto",
          flex: 1
        }}><div style={{
            fontSize: 11,
            color: dim,
            marginBottom: 10
          }}>Selected physical platform · 5 upcoming</div>{board(active, true)}<div style={{
            display: "flex",
            gap: 8
          }}>{action(saved.some(v => v.id === active.id) ? "✓ Saved" : "Save platform", () => save(active), true)}{action("Refresh", () => setStale(false))}</div><p style={{
            fontSize: 11,
            color: dim,
            lineHeight: 1.5
          }}>These are illustrative predictions, not journey advice.</p></div></>}
{page === "search" && <>{heading("Search stations")}<div style={{
          overflowY: "auto",
          padding: 12,
          flex: 1
        }}><div style={{
            display: "flex",
            alignItems: "center",
            gap: 9,
            padding: "0 12px",
            border: "1px solid " + border,
            background: surface,
            borderRadius: 10,
            marginBottom: 13
          }}><Search size={16} color={dim} /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Station name" style={{
              height: 46,
              border: 0,
              outline: "none",
              background: "transparent",
              color: fg,
              fontSize: 14,
              flex: 1
            }} /></div>{query.trim() ? <><div style={{
              color: dim,
              fontSize: 11,
              fontWeight: 700,
              margin: "18px 2px 9px"
            }}>SEARCH RESULTS</div>{stations.filter(n => n.toLowerCase().includes(query.trim().toLowerCase())).length ? stations.filter(n => n.toLowerCase().includes(query.trim().toLowerCase())).map(n => <React.Fragment key={n}>{result(n, "Northern line", () => selectStation(n))}</React.Fragment>) : <p style={{
              color: dim,
              fontSize: 12
            }}>No stations found. Try another search.</p>}</> : <><div style={{
              color: dim,
              fontSize: 11,
              fontWeight: 700,
              margin: "18px 2px 9px"
            }}>RECENT SEARCHES</div>{recent.length ? recent.map(n => <React.Fragment key={n}>{result(n, "Northern line", () => selectStation(n))}</React.Fragment>) : <p style={{
              color: dim,
              fontSize: 12
            }}>Your two most recent searches will appear here.</p>}</>}</div></>}
{page === "platforms" && <>{heading("Select platform")}<div style={{
          overflowY: "auto",
          padding: 12,
          flex: 1
        }}><h2 style={{
            fontSize: 22,
            margin: "5px 0"
          }}>{selected}</h2><p style={{
            fontSize: 12,
            color: dim
          }}>Select a physical platform and direction.</p>{["Southbound", "Northbound"].map((direction, j) => <section key={direction}><h3 style={{
              fontSize: 11,
              letterSpacing: 1.4,
              color: dim,
              marginTop: 22
            }}>{direction.toUpperCase()}</h3>{["A", "B"].map((letter, i) => result("Platform " + letter, direction, () => {
              const id = selected + direction + letter;
              setActive(saved.find(p => p.id === id) || {
                id,
                name: selected,
                direction,
                platform: "Platform " + letter,
                lines: ["Northern"],
                trains: sample[(i + j) % 3].trains
              });
              setPage("detail");
            }))}</section>)}<p style={{
            fontSize: 11,
            color: dim
          }}>Platform letters are placeholders pending verification.</p></div></>}
{page === "manage" && <>{heading(incoming ? "Replace a platform" : "Manage platforms")}<div style={{
          overflowY: "auto",
          padding: 12,
          flex: 1
        }}><p style={{
            fontSize: 12,
            lineHeight: 1.5,
            color: dim
          }}>{incoming ? "Choose the saved platform to replace with " + incoming.name + "." : "Drag the handle to reorder. Tap a card to customise its display."}</p>{saved.map((p, i) => <div key={p.id} data-platform-id={p.id} style={{
            opacity: dragging === p.id ? .55 : 1,
            boxShadow: dragTarget === p.id && dragging !== p.id ? "0 -2px 0 #E5A542" : "none",
            display: "flex",
            gap: 6,
            alignItems: "center",
            marginBottom: 8
          }}>{!incoming && <button aria-label={"Drag to reorder " + p.name + "; use arrow keys to move"} onPointerDown={e => {
              e.currentTarget.setPointerCapture(e.pointerId);
              dragFrom.current = p.id;
              dragTo.current = p.id;
              setDragging(p.id);
              setDragTarget(p.id);
            }} onPointerMove={e => {
              if (!dragFrom.current) return;
              const row = document.elementFromPoint(e.clientX, e.clientY)?.closest("[data-platform-id]");
              const target = row?.getAttribute("data-platform-id");
              if (target) {
                dragTo.current = target;
                setDragTarget(target);
              }
            }} onPointerUp={() => {
              if (dragFrom.current && dragTo.current) reorder(dragFrom.current, dragTo.current);
              dragFrom.current = null;
              dragTo.current = null;
              setDragging(null);
              setDragTarget(null);
            }} onPointerCancel={() => {
              dragFrom.current = null;
              dragTo.current = null;
              setDragging(null);
              setDragTarget(null);
            }} onKeyDown={e => {
              if (e.key === "ArrowUp" || e.key === "ArrowDown") {
                e.preventDefault();
                const target = saved[i + (e.key === "ArrowUp" ? -1 : 1)];
                if (target) reorder(p.id, target.id);
              }
            }} style={{
              background: "none",
              border: 0,
              color: dim,
              cursor: "grab",
              touchAction: "none",
              padding: "10px 4px",
              marginTop: -8
            }}><GripVertical size={19} /></button>}<div style={{
              flex: 1
            }}>{result(p.name, p.direction + " · " + p.platform, () => {
                if (incoming) {
                  setSaved(saved.map(v => v.id === p.id ? incoming : v));
                  setIncoming(null);
                  setPage("home");
                } else {
                  setEditingCard(p);
                  setPage("editCard");
                }
              })}</div>{!incoming && <button aria-label={"Remove " + p.name} onClick={() => {
              setUndo([...saved]);
              setSaved(saved.filter(v => v.id !== p.id));
            }} style={{
              background: "none",
              border: 0,
              color: "#E98383",
              cursor: "pointer",
              marginTop: -8
            }}><Trash2 size={18} /></button>}</div>)}{undo && action("Undo removal", () => {
            setSaved(undo);
            setUndo(null);
          })}{action("Done", () => {
            setIncoming(null);
            setPage("home");
          }, true)}</div></>}
{page === "settings" && <>{heading("Settings")}<div style={{
          padding: 12,
          flex: 1,
          overflowY: "auto"
        }}>
  <p style={{
            color: dim,
            fontSize: 12,
            lineHeight: 1.5,
            margin: "4px 2px 14px"
          }}>Choose how NextBranch looks and manage your saved platforms.</p>
  {result("Appearance", "Card display and interface", () => setPage("ui"))}
  {result("Manage cards", "Customise, reorder or remove platforms", () => setPage("manage"))}
</div></>}
{page === "ui" && <>{heading("Appearance")}<div style={{
          padding: 12,
          flex: 1,
          overflowY: "auto"
        }}>
  <div style={{
            fontSize: 11,
            color: dim,
            fontWeight: 700,
            letterSpacing: ".08em",
            margin: "7px 2px 8px",
            textTransform: "uppercase"
          }}>Card display</div>
  <p style={{
            color: dim,
            fontSize: 12,
            lineHeight: 1.5,
            margin: "0 2px 14px"
          }}>Choose one style for every card, or customise each card individually.</p>
  {([["custom", "Custom for each card", "Choose a style in Manage cards"], ["matrix", "Amber for all", "Classic dot-matrix departures"], ["modern", "Modern for all", "Clean, blue departure display"]] as const).map(([value, title, detail]) => <button key={value} onClick={() => setBoardStyle(value)} aria-pressed={boardStyle === value} style={{
            width: "100%",
            textAlign: "left",
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            padding: "14px",
            marginBottom: 8,
            borderRadius: 10,
            background: surface,
            color: fg,
            border: "1px solid " + (boardStyle === value ? "#E5A542" : border),
            cursor: "pointer"
          }}><span><strong style={{
                display: "block",
                fontSize: 14
              }}>{title}</strong><span style={{
                display: "block",
                marginTop: 4,
                color: dim,
                fontSize: 11
              }}>{detail}</span></span><span aria-hidden="true" style={{
              color: "#E5A542",
              fontSize: 16
            }}>{boardStyle === value ? "✓" : ""}</span></button>)}
  {boardStyle === "custom" && <div style={{
            marginTop: 15
          }}>{action("Manage card styles", () => setPage("manage"))}</div>}
</div></>}
{page === "editCard" && editingCard && <>{heading("Card display")}<div style={{
          padding: 12,
          flex: 1,
          overflowY: "auto"
        }}>
  <div style={{
            margin: "4px 2px 14px"
          }}><strong style={{
              fontSize: 16
            }}>{editingCard.name}</strong><div style={{
              color: dim,
              fontSize: 11,
              marginTop: 4
            }}>{editingCard.direction} · {editingCard.platform}</div></div>
  <p style={{
            fontSize: 12,
            color: dim,
            lineHeight: 1.5
          }}>Choose a display for this card. Selecting a style switches card display to Custom.</p>
  {([["matrix", "Amber", "Classic dot-matrix departures"], ["modern", "Modern", "Clean, blue departure display"]] as const).map(([value, title, detail]) => <button key={value} aria-pressed={(cardStyles[editingCard.id] || "matrix") === value} onClick={() => {
            setCardStyles({
              ...cardStyles,
              [editingCard.id]: value
            });
            setBoardStyle("custom");
          }} style={{
            width: "100%",
            textAlign: "left",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            padding: "14px",
            marginBottom: 8,
            borderRadius: 10,
            background: surface,
            color: fg,
            border: "1px solid " + ((cardStyles[editingCard.id] || "matrix") === value ? "#E5A542" : border),
            cursor: "pointer"
          }}><span><strong style={{
                display: "block",
                fontSize: 14
              }}>{title}</strong><span style={{
                display: "block",
                marginTop: 4,
                color: dim,
                fontSize: 11
              }}>{detail}</span></span><span style={{
              color: "#E5A542"
            }}>{(cardStyles[editingCard.id] || "matrix") === value ? "✓" : ""}</span></button>)}
  <div style={{
            marginTop: 16
          }}>{action("Done", () => setPage("manage"), true)}</div>
</div></>}
<div style={{
        height: 23,
        background: surface,
        flexShrink: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center"
      }}><span style={{
          height: 4,
          width: 105,
          borderRadius: 20,
          background: fg
        }} /></div></div></div>;
};

@import url('https://fonts.googleapis.com/css2?family=Avenir+Next:wght@400&display=swap');
@import 'tailwindcss';

@plugin "tailwindcss-animate";

@custom-variant dark (&:is(.dark *));

body {
  margin: 0;
  padding: 0;
  display: flex;
  width: 100%;
  height: 100%;
  min-height: 100vh;
  box-sizing: border-box;
  overflow: auto;
  overscroll-behavior-x: none;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-geist-sans);
  --font-body: var(--font-body);
  --font-heading: var(--font-heading);
  --font-mono: var(--font-geist-mono);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
}

:root {
  --radius: 0.625rem;
  --background: oklch(1 0 0);
  --foreground: oklch(0.145 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.145 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.145 0 0);
  --primary: oklch(0.205 0 0);
  --primary-foreground: oklch(0.985 0 0);
  --secondary: oklch(0.97 0 0);
  --secondary-foreground: oklch(0.205 0 0);
  --muted: oklch(0.97 0 0);
  --muted-foreground: oklch(0.556 0 0);
  --accent: oklch(0.97 0 0);
  --accent-foreground: oklch(0.205 0 0);
  --destructive: oklch(0.577 0.245 27.325);
  --border: oklch(0.922 0 0);
  --input: oklch(0.922 0 0);
  --ring: oklch(0.708 0 0);
  --chart-1: oklch(0.646 0.222 41.116);
  --chart-2: oklch(0.6 0.118 184.704);
  --chart-3: oklch(0.398 0.07 227.392);
  --chart-4: oklch(0.828 0.189 84.429);
  --chart-5: oklch(0.769 0.188 70.08);
  --sidebar: oklch(0.985 0 0);
  --sidebar-foreground: oklch(0.145 0 0);
  --sidebar-primary: oklch(0.205 0 0);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.97 0 0);
  --sidebar-accent-foreground: oklch(0.205 0 0);
  --sidebar-border: oklch(0.922 0 0);
  --sidebar-ring: oklch(0.708 0 0);
}

.dark {
  --background: oklch(0.145 0 0);
  --foreground: oklch(0.985 0 0);
  --card: oklch(0.205 0 0);
  --card-foreground: oklch(0.985 0 0);
  --popover: oklch(0.205 0 0);
  --popover-foreground: oklch(0.985 0 0);
  --primary: oklch(0.922 0 0);
  --primary-foreground: oklch(0.205 0 0);
  --secondary: oklch(0.269 0 0);
  --secondary-foreground: oklch(0.985 0 0);
  --muted: oklch(0.269 0 0);
  --muted-foreground: oklch(0.708 0 0);
  --accent: oklch(0.269 0 0);
  --accent-foreground: oklch(0.985 0 0);
  --destructive: oklch(0.704 0.191 22.216);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(1 0 0 / 15%);
  --ring: oklch(0.556 0 0);
  --chart-1: oklch(0.488 0.243 264.376);
  --chart-2: oklch(0.696 0.17 162.48);
  --chart-3: oklch(0.769 0.188 70.08);
  --chart-4: oklch(0.627 0.265 303.9);
  --chart-5: oklch(0.645 0.246 16.439);
  --sidebar: oklch(0.205 0 0);
  --sidebar-foreground: oklch(0.985 0 0);
  --sidebar-primary: oklch(0.488 0.243 264.376);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.269 0 0);
  --sidebar-accent-foreground: oklch(0.985 0 0);
  --sidebar-border: oklch(1 0 0 / 10%);
  --sidebar-ring: oklch(0.556 0 0);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
    font-family: var(--font-body);
  }
  h1,
  h2,
  h3,
  h4,
  h5,
  h6 {
    font-family: var(--font-heading);
  }
  html,
  body,
  #root {
    height: 100%;
    width: 100%;
    margin: 0;
    padding: 0;
    overscroll-behavior-x: none;
  }
}

/* Broken Image Fallback Styles */
img.broken-image-fallback {
  position: relative;
  display: inline-block;
  background: #f9fafb;
  border: 1px solid #e5e7eb;
  object-fit: none;
  object-position: center;
  animation: fadeIn 0.3s ease-in-out;
}

.dark img.broken-image-fallback {
  background: #1f2937;
  border-color: #374151;
}

@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
